// Deduplicatie via workflow static data (overleeft n8n-herstart)
const workflowData = $getWorkflowStaticData('global');
if (!workflowData.processedLinks) {
  workflowData.processedLinks = [];
}

const allItems = $input.all();
const newItems = allItems.filter(item => {
  const link = item.json.link || item.json.url || '';
  return link && !workflowData.processedLinks.includes(link);
});

for (const item of newItems) {
  const link = item.json.link || item.json.url;
  workflowData.processedLinks.push(link);
}

// Bewaar maximaal 1000 links
if (workflowData.processedLinks.length > 1000) {
  workflowData.processedLinks = workflowData.processedLinks.slice(-1000);
}

return newItems;

const rssItem = $('RSS Feed').item.json;
let recipe;

try {
  let raw = $input.item.json.message?.content
    || $input.item.json.choices?.[0]?.message?.content
    || $input.item.json.text || '';
  raw = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  recipe = JSON.parse(raw);
} catch (e) {
  recipe = {
    title: rssItem.title || 'Onbekend Recept',
    cuisine: null, course: null, servings: null,
    time_prep: null, time_cook: null, time_total: null,
    ingredients: [], steps: [],
    description: rssItem.contentSnippet || '',
    tags: []
  };
}

const today = new Date().toISOString().split('T')[0];
const title = recipe.title || rssItem.title || 'Onbekend Recept';
const safeTitle = title.replace(/[\/\\?%*:|"<>]/g, '-').trim();

// Ingrediënten als wikilinks naar 02 Ingredients
const ingredientLines = (recipe.ingredients || []).map(ing => {
  const match = ing.match(/^[\d\s\.,\/]+(el|tl|eetl|theel|kg|g|mg|ml|l|dl|cl|blik|blikje|teen|tanden|stuk|stuks|bosje|handvol|snuf|mespunt|scheut|grote|kleine|verse)?\s+(.+)$/i);
  const name = match ? match[2].trim() : ing.trim();
  return `- ${ing} — [[${name}]]`;
}).join('\n');

const steps = (recipe.steps || []).map((step, i) => `${i + 1}. ${step}`).join('\n');

const tags = ['recipe', ...(recipe.tags || [])];
if (recipe.cuisine) tags.push(`cuisine/${recipe.cuisine.toLowerCase()}`);
if (recipe.course) tags.push(`course/${recipe.course.toLowerCase()}`);

const fm = [
  '---',
  `title: "${title.replace(/"/g, '\\"')}"`,
  `source: "${rssItem.link || ''}"`,
  `date_added: ${today}`,
  `cuisine: ${recipe.cuisine || ''}`,
  `course: ${recipe.course || ''}`,
  `servings: ${recipe.servings || ''}`,
  `time_prep: ${recipe.time_prep || ''}`,
  `time_cook: ${recipe.time_cook || ''}`,
  `time_total: ${recipe.time_total || ''}`,
  `rating: `,
  `tried: false`,
  `tags:`,
  ...tags.map(t => `  - ${t}`),
  '---'
].join('\n');

const note = [
  fm, '',
  `# ${title}`, '',
  `> ${recipe.description || ''}`, '',
  '## Ingrediënten', '',
  ingredientLines || '- ', '',
  '## Bereiding', '',
  steps || '1. ', '',
  '## Notities', ''
].join('\n');

// GitHub API vereist base64-gecodeerde content
const contentBase64 = Buffer.from(note, 'utf8').toString('base64');

return [{
  json: {
    filename: safeTitle,
    content: note,
    contentBase64,
    path: `01 Recipes/${safeTitle}.md`
  }
}];
